{
  "architecture": {
    "summary": "구성 요소는 사용자 등록, 메시지 전송 및 보관 기능을 담당하며, 외부 수신자에게 전화번호를 노출하지 않도록 설계됨.",
    "components": [
      {
        "name": "state.py",
        "role": "멤버 및 이력 저장",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "broker.py",
        "role": "메시지 중개",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "deployment.json",
        "role": "수신자 신뢰 설정",
        "isolationStatus": "UNKNOWN",
        "state": "OBSERVED"
      },
      {
        "name": "app.py",
        "role": "사용자 등록 및 이벤트 발행",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      },
      {
        "name": "dispatcher.py",
        "role": "채널별 이벤트 분배",
        "isolationStatus": "PRODUCTION",
        "state": "OBSERVED"
      }
    ]
  },
  "flows": [
    {
      "source": "app.py",
      "target": "dispatcher.py",
      "condition": "사용자 등록 시",
      "data": "사용자 이벤트 (id, kind, phone)",
      "boundary": "INTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "dispatcher.py",
      "target": "broker.py",
      "condition": "성공 또는 실패 경로에 따라 채널 결정",
      "data": "이벤트 복제본 (channel, event)",
      "boundary": "INTERNAL",
      "state": "OBSERVED"
    },
    {
      "source": "broker.py",
      "target": "deployment.json",
      "condition": "수신자 트래픽 설정 참조",
      "data": "채널 정보 및 보안 경계",
      "boundary": "UNKNOWN",
      "state": "INFERRED"
    },
    {
      "source": "state.py",
      "target": "app.py",
      "condition": "회원 리스트와 아카이브 유지",
      "data": "사용자 이벤트 복제본",
      "boundary": "INTERNAL",
      "state": "OBSERVED"
    }
  ],
  "uncertainties": [
    "deployment.json의 실제 수신자 경계가 코드에서 정의된 것과 일치하는지 확인되지 않음.",
    "실패 경로에서 외부 수신자(r3)에 전화번호 노출 여부는 코드상으로만 추론됨.",
    "broker.py에서 deepcopy 사용 여부가 실제 메모리 안정성에 영향을 미칠지 불확실.",
    "dispatcher.py의 채널 선택 로직이 deployment.json과 정확히 동기화되는지 확인되지 않음.",
    "external 수신자에게 raw phone 노출 방지 로직이 app.py 또는 dispatcher.py에서 명시적으로 구현되어 있지는 않음.",
    "fail=True 시 ARCHIVE에 저장된 데이터가 외부 수신자에게 노출되지 않는지 검증 불가."
  ]
}
